def process_orders(orders):
    total = 0.0
    failed = []
    for order in orders:
        oid = order.get('id') if isinstance(order, dict) else None
        try:
            subtotal = float(order['amount']) * int(order['quantity'])
        except (KeyError, TypeError, ValueError):
            failed.append(oid)
            continue
        total += subtotal
    return {"revenue": total, "failed_orders": failed}
